//! About page (`/system/about`) and the open-source licenses page (`/system/licenses`).
//!
//! Both work without internet access: the licenses text is `THIRD-PARTY-LICENSES.txt`, generated by
//! `ci/third-party-licenses.py` and copied next to the UI by trunk (see `index.html`), so the node
//! serves it itself. The policy pages are on the project site and open in a new tab.
use leptos::*;
use leptos_router::A;

/// Version of this UI build (the workspace version the UI crate inherits).
pub const UI_VERSION: &str = env!("CARGO_PKG_VERSION");

/// Where the UI serves the generated license inventory from (same origin, no auth needed).
pub const LICENSES_PATH: &str = "/THIRD-PARTY-LICENSES.txt";

/// Project documentation; these are upstream documentation addresses, not node settings.
pub const SITE_DOCS: &str = "https://horcrux.errant.solutions/docs/";
pub const SOURCE_URL: &str = "https://github.com/CanuteTheGreat/horcrux";
/// Where to support the project financially (one link on this page, nothing else).
pub const SUPPORT_URL: &str = "https://errant.solutions/support/horcrux";

#[component]
pub fn AboutPage() -> impl IntoView {
    view! {
        <div class="about-page">
            <div class="page-header">
                <h1>"About Horcrux"</h1>
            </div>
            <p class="help-text">
                "Horcrux is free software (GPL-3.0). This is web UI version " <strong>{UI_VERSION}</strong> "."
            </p>
            <div class="card">
                <h2>"Policies and licenses"</h2>
                <ul class="about-links">
                    <li>
                        <A href="/system/licenses">"Open-source licenses"</A>
                        " - the licenses of every third-party Rust crate in this build, available offline."
                    </li>
                    <li>
                        <a href=format!("{SITE_DOCS}privacy/") target="_blank" rel="noopener">"Privacy"</a>
                        " - what Horcrux sends off the machine (no telemetry; software updates; what you configure)."
                    </li>
                    <li>
                        <a href=format!("{SITE_DOCS}update-policy/") target="_blank" rel="noopener">"Updates, supported versions and rollback"</a>
                        " - version numbers, the security-fix window and how to go back (System > Boot Environments)."
                    </li>
                    <li>
                        <a href=format!("{SOURCE_URL}/blob/main/CHANGELOG.md") target="_blank" rel="noopener">"Release notes (CHANGELOG)"</a>
                    </li>
                    <li>
                        <a href=format!("{SOURCE_URL}/blob/main/LICENSE") target="_blank" rel="noopener">"Horcrux license"</a>
                    </li>
                    <li>
                        <a href=SOURCE_URL target="_blank" rel="noopener">"Source code"</a>
                    </li>
                    <li>
                        <a id="support-link" href=SUPPORT_URL target="_blank" rel="noopener">"Support Horcrux"</a>
                        " - a one-time tip or a monthly sponsorship; the software stays free either way."
                    </li>
                </ul>
            </div>
        </div>
    }
}

#[component]
pub fn LicensesPage() -> impl IntoView {
    let (text, set_text) = create_signal(None::<String>);
    let (error, set_error) = create_signal(None::<String>);

    let load = create_action(move |_: &()| async move {
        set_error.set(None);
        let fetched = match reqwasm::http::Request::get(LICENSES_PATH).send().await {
            Ok(r) if r.ok() => r.text().await.map_err(|e| e.to_string()),
            Ok(r) => Err(crate::api::error_text(r.status(), "")),
            Err(e) => Err(e.to_string()),
        };
        match fetched {
            Ok(t) => set_text.set(Some(t)),
            Err(e) => set_error.set(Some(format!("Could not load the license list: {e}"))),
        }
    });
    load.dispatch(());

    view! {
        <div class="licenses-page">
            <div class="page-header">
                <h1>"Open-source licenses"</h1>
                <div class="header-actions">
                    <a class="btn btn-secondary" href=LICENSES_PATH download="THIRD-PARTY-LICENSES.txt">"Download as text"</a>
                    <A href="/system/about" class="btn btn-secondary">"About"</A>
                </div>
            </div>
            <p class="help-text">
                "Horcrux is built from free software. This is the license of every third-party Rust crate that can be part of "
                "a Horcrux build, followed by the license texts. Operating-system packages carry their own licenses "
                "(on the node: " <code>"equery meta <package>"</code> ")."
            </p>
            {move || error.get().map(|m| view! {
                <div class="alert alert-error">
                    {m} " "
                    <a href=LICENSES_PATH>"Open the file directly"</a>
                </div>
            })}
            {move || match (text.get(), error.get()) {
                (Some(t), _) => view! { <pre class="licenses-text">{t}</pre> }.into_view(),
                (None, None) => view! { <p class="help-text">"Loading..."</p> }.into_view(),
                (None, Some(_)) => ().into_view(),
            }}
        </div>
    }
}
